657	public enum Xzn53Status {
658	    PENDING {
659	        @Override
660	        public boolean canTransitionTo(Xzn53Status nextStatus) {
661	            return nextStatus == SHIPPED || nextStatus == CANCELED;
662	        }
663	    },
664	    SHIPPED {
665	        @Override
666	        public boolean canTransitionTo(Xzn53Status nextStatus) {
667	            return nextStatus == IN_TRANSIT || nextStatus == RETURNED || nextStatus == CANCELED;
668	        }
669	    },
670	    IN_TRANSIT {
671	        @Override
672	        public boolean canTransitionTo(Xzn53Status nextStatus) {
673	            return nextStatus == OUT_FOR_DELIVERY || nextStatus == DELAYED || nextStatus == CANCELED
674	                    || nextStatus == DELIVERED;
675	        }
676	    },
677	    OUT_FOR_DELIVERY {
678	        @Override
679	        public boolean canTransitionTo(Xzn53Status nextStatus) {
680	            return nextStatus == DELIVERED || nextStatus == FAILED_DELIVERY || nextStatus == CANCELED;
681	        }
682	    },
683	    DELIVERED {
684	        @Override
685	        public boolean canTransitionTo(Xzn53Status nextStatus) {
686	            return false;
687	        }
688	    },
689	    RETURNED {
690	        @Override
691	        public boolean canTransitionTo(Xzn53Status nextStatus) {
692	            return nextStatus == CANCELED;
693	        }
694	    },
695	    CANCELED {
696	        @Override
697	        public boolean canTransitionTo(Xzn53Status nextStatus) {
698	            return false;
699	        }
