308	    @Transactional
309	    public void updateShipmentStatuses() {
310	        log.info("전체 배송 상태 업데이트 시작");
311	
312	
313	        List<Xfr60> shipments = orderShipmentRepository.findByStatusIn(
314	                List.of(Xzn53Status.IN_TRANSIT, Xzn53Status.OUT_FOR_DELIVERY)
315	        );
316	
317	        log.debug("업데이트 대상 배송 조회: 총 {}건", shipments.size());
318	
319	        int successCount = 0;
320	        int errorCount = 0;
321	
322	        for (Xfr60 shipment : shipments) {
323	            try {
324	                String trackingNumber = shipment.getTrackingNumber();
325	                if (trackingNumber == null || trackingNumber.isBlank()) {
326	                    log.warn("운송장 번호가 없는 배송건 스킵: shipmentId={}", shipment.getId());
327	                    errorCount++;
328	                    continue;
329	                }
330	
331	                log.debug("배송 상태 조회 시작: shipmentId={}, trackingNumber={}",
332	                        shipment.getId(), trackingNumber);
333	
334	
335	                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
336	                Xzn53Status newStatus = mapToShipmentStatus(currentStatus);
337	
338	                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}, newStatus={}",
339	                        shipment.getId(), currentStatus, newStatus);
340	
341	
342	                if (shipment.getStatus() == newStatus) {
343	                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
344	                            shipment.getId(), newStatus);
345	                    successCount++;
346	                    continue;
347	                }
348	
349	
350	                if (newStatus == Xzn53Status.DELIVERED) {
351	                    log.info("배송 완료 처리: shipmentId={}", shipment.getId());
352	
353	                    shipment.updateStatus(newStatus);
354	                    Xhq12 order = shipment.getOrder();
355	                    order.updateStatus(Xhq12Status.COMPLETED);
356	
357	
358	                    Xjm45 buyer = order.getUser();
359	                    notificationCommandService.createNotification(
360	                            buyer.getId(),
361	                            Xrv73.SHOPPING,
362	                            Xbp24Type.BID,
363	                            "상품이 배송 완료되었습니다. 주문 ID: " + order.getId()
364	                    );
365	
366	                    log.info("배송 완료 알림 전송: userId={}, orderId={}",
367	                            buyer.getId(), order.getId());
368	
369	                } else if (newStatus == Xzn53Status.OUT_FOR_DELIVERY &&
370	                        shipment.getStatus() != Xzn53Status.OUT_FOR_DELIVERY) {
371	                    log.info("배송 출발 처리: shipmentId={}", shipment.getId());
372	                    shipment.updateStatus(Xzn53Status.OUT_FOR_DELIVERY);
373	
374	                } else {
375	                    log.debug("기타 상태 업데이트: shipmentId={}, newStatus={}",
376	                            shipment.getId(), newStatus);
377	                    shipment.updateStatus(newStatus);
378	                }
379	
380	                orderShipmentRepository.save(shipment);
381	                successCount++;
382	
383	            } catch (Exception e) {
384	                log.error("배송 상태 업데이트 실패: shipmentId={}, error={}",
385	                        shipment.getId(), e.getMessage(), e);
386	                errorCount++;
387	            }
388	        }
389	
390	        log.info("전체 배송 상태 업데이트 완료: 성공={}건, 실패={}건", successCount, errorCount);
391	    }
